<?php declare(strict_types=1); require __DIR__.'/action-common.php';admin_post();try{$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$company=$id===false?null:$application->adminCompanies()->find($id);if(!$company||($company['status']??'')==='bloqueado')throw new RuntimeException('Empresa indisponível.');$application->adminAccesses()->enter($company,$currentUser->id(),(string)($_SERVER['REMOTE_ADDR']??''),$application->activeCompanyContext());$session->regenerateId();$session->flash('success','Acesso administrativo iniciado.');admin_action_redirect('adm/empresa.php?id='.$id);}catch(\Throwable $e){admin_action_error($e,'adm/empresas.php');}
